import {buttonName} from 'tiny_eduplay/common';
import {addToolbarButtons} from 'editor_tiny/utils';

const configureMenu = (menu) => {
    // Add the EduPlay item to the Insert menu.
    if (menu.insert && !menu.insert.items.includes(buttonName)) {
        menu.insert.items = `${menu.insert.items} ${buttonName}`;
    }
    return menu;
};

export const configure = (instanceConfig) => ({
    menu: configureMenu(instanceConfig.menu),
    toolbar: addToolbarButtons(instanceConfig.toolbar, 'content', [buttonName]),
});
